fn putd(o:[*]u8,p:usize,x:f64)void{const b=@as(u64,@bitCast(x));for(0..8)|k|o[p+k]=@truncate(b>>(8*k));}
fn sig(x:f64)f64{return 1.0/(1.0+@exp(-x));}
export fn neural_network(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n<7)return -1;const ni=v[0];const nh=v[1];const no=v[2];if(ni<1 or ni>3 or nh<1 or nh>3 or no<1 or no>3 or n!=@as(usize,@intCast(3+ni+ni*nh+nh*no)))return -1;for(3..n)|i|{if(v[i] < -1000 or v[i]>1000)return -1;}if(cap<@as(usize,@intCast(no))*8)return -2;const xs:usize=3;const w1=xs+@as(usize,@intCast(ni));const w2=w1+@as(usize,@intCast(ni*nh));var h=[_]f64{0}**3;for(0..@intCast(nh))|j|{var z:f64=0;for(0..@intCast(ni))|i|z+=@as(f64,@floatFromInt(v[xs+i]))/1000.0*(@as(f64,@floatFromInt(v[w1+i*@as(usize,@intCast(nh))+j]))/1000.0);h[j]=sig(z);}for(0..@intCast(no))|j|{var z:f64=0;for(0..@intCast(nh))|i|z+=h[i]*(@as(f64,@floatFromInt(v[w2+i*@as(usize,@intCast(no))+j]))/1000.0);putd(o,j*8,sig(z));}return no*8;}
